import React from "react";
import { useNavigate } from "react-router-dom";

export default function Navbar({ user, onLogout }) {
  const navigate = useNavigate();

  const goToSection = (sectionId) => {
    // 1. Navigate to home page
    navigate("/");

    // 2. Then scroll after page loads
    setTimeout(() => {
      const el = document.getElementById(sectionId);
      if (el) {
        el.scrollIntoView({ behavior: "smooth" });
      }
    }, 100);
  };

  return (
    <nav className="nav">
      <div className="brand" onClick={() => goToSection("home-section")}>
        NGO Portal
      </div>

      <div className="links">
        <button onClick={() => goToSection("home-section")}>Home</button>
        <button onClick={() => goToSection("about-section")}>About Us</button>
        <button onClick={() => goToSection("events-section")}>Events</button>
        <button onClick={() => goToSection("contact-section")}>Contact</button>

        {!user && <button onClick={() => navigate("/login")}>Login</button>}
        {!user && <button onClick={() => navigate("/register")}>Register</button>}
        {user && <button onClick={() => navigate("/dashboard")}>Dashboard</button>}
        {user && <button onClick={onLogout}>Logout</button>}
      </div>
    </nav>
  );
}
